package resolvermaterialize

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"slices"
	"strings"
	"testing"

	"github.com/bmeddeb/phebs/internal/extract/extractors/gocaller"
	"github.com/bmeddeb/phebs/internal/extract/sdk"
)

// PHEBS-48 fixtures, modelled on cadence's client/wrappers/thrift: the
// wrapper struct and its client field are declared in constructor.go, and the
// calls through g.c are made from a sibling gowrap-generated file.
const (
	wrapperConstructorPath = "client/wrappers/thrift/constructor.go"
	wrapperCallsPath       = "client/wrappers/thrift/echo_generated.go"
	wrapperConstructor     = `package thrift

import "example.test/thrift/echo/echoclient"

type (
	echoClient struct {
		c echoclient.Interface
	}
	embeddingClient struct {
		echoclient.Interface
	}
)

func NewEchoClient(c echoclient.Interface) echoClient { return echoClient{c} }
`
	wrapperCalls = `// Code generated by gowrap. DO NOT EDIT.

package thrift

import "context"

func (g echoClient) Echo(ctx context.Context, ping string) (string, error) {
	return g.c.Echo(ctx, ping)
}

func (e embeddingClient) PingTwice(ctx context.Context) error {
	return e.PingTwice(ctx)
}
`
)

type scannedCall struct{ operation, role string }

func scanSource(t *testing.T, resolver *gocaller.DirectResolver, filePath, source string) (calls []scannedCall, unresolved []string) {
	t.Helper()
	sum := sha256.Sum256([]byte(source))
	if _, err := gocaller.ScanDirectSyntaxFile(context.Background(), gocaller.DirectScanRequest{
		Protocol: "thrift", Path: filePath,
		Blob:     sdk.Blob{Content: source, Digest: "sha256:" + hex.EncodeToString(sum[:])},
		Resolver: resolver, ResolverCatalogDigest: "sha256:" + strings.Repeat("a", 64),
	}, func(fact sdk.Fact) error {
		switch fact.Assertion.Predicate {
		case "CALLS_OPERATION":
			if fact.Assertion.Lineage != yarpcLineage {
				t.Errorf("call %s lineage = %q", fact.Assertion.Object, fact.Assertion.Lineage)
			}
			calls = append(calls, scannedCall{operation: fact.Assertion.Object, role: fact.Assertion.CodeRole})
		case "UNRESOLVED_CALLER":
			unresolved = append(unresolved, fact.Assertion.Object)
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	slices.SortFunc(calls, func(left, right scannedCall) int { return strings.Compare(left.operation, right.operation) })
	return calls, unresolved
}

func callOperations(calls []scannedCall) []string {
	result := make([]string, 0, len(calls))
	for _, call := range calls {
		result = append(result, call.operation)
	}
	return result
}

// TestPackageStructFieldsResolveCrossFileCallers is the PHEBS-48 core: a
// named and an embedded client field declared in a sibling file resolve, and
// a resolver compiled from the same descriptors without the projection (the
// pre-PHEBS-48 behavior) finds none of them.
func TestPackageStructFieldsResolveCrossFileCallers(t *testing.T) {
	if PackVersion != "1.6.0" || PackageStructRule != "package-struct-fields-v1" ||
		FrozenMaterializationPolicy().PackageStructRule != PackageStructRule ||
		FrozenMaterializationPolicy().MaxPackageStructFields != MaxPackageStructFields {
		t.Fatalf("package struct identity = %q / %q", PackageStructRule, PackVersion)
	}
	view := buildYARPCCatalog(t, yarpcFixture{embedded: true, extra: map[string]string{
		wrapperConstructorPath: wrapperConstructor, wrapperCallsPath: wrapperCalls,
	}})
	if view.packageStructScan != 1 || len(view.packageStructs) != 2 {
		t.Fatalf("projection = %d scan rows, fields %+v", view.packageStructScan, view.packageStructs)
	}
	for _, field := range view.packageStructs {
		if field.Directory != "client/wrappers/thrift" || field.Package != "thrift" ||
			field.SourcePath != wrapperConstructorPath || field.ClientType != "Interface" ||
			field.ImportPath != "example.test/thrift/echo/echoclient" {
			t.Fatalf("projected field = %+v", field)
		}
	}
	calls, unresolved := scanSource(t, view.Resolver(), wrapperCallsPath, wrapperCalls)
	want := []string{"/echo.Echo/echo", "/echo.Echo/ping_twice"}
	if !slices.Equal(callOperations(calls), want) || len(unresolved) != 0 {
		t.Fatalf("cross-file calls = %+v (unresolved %v), want %v", calls, unresolved, want)
	}
	for _, call := range calls {
		if call.role != "generated" {
			t.Fatalf("generated wrapper call role = %q", call.role)
		}
	}
	// Mutation: the same descriptors without the projection.
	bare, err := gocaller.NewDirectResolver(context.Background(), "thrift", view.Descriptors())
	if err != nil {
		t.Fatal(err)
	}
	if calls, unresolved := scanSource(t, bare, wrapperCallsPath, wrapperCalls); len(calls) != 0 || len(unresolved) != 0 {
		t.Fatalf("calls without the projection = %+v (unresolved %v); want none", calls, unresolved)
	}
	// The declaring file's own same-file rule is unchanged.
	if calls, _ := scanSource(t, view.Resolver(), wrapperConstructorPath, wrapperConstructor); len(calls) != 0 {
		t.Fatalf("constructor file emitted calls: %+v", calls)
	}
}

// TestPackageStructFieldsAbstainOnUncertainPackages covers each shape that
// must contribute nothing: build-tag variants declaring the struct twice, an
// unparseable sibling, a struct declared under the x_test package clause, and
// a scanned file that declares the struct name itself.
func TestPackageStructFieldsAbstainOnUncertainPackages(t *testing.T) {
	variant := strings.Replace(wrapperConstructor, "func NewEchoClient(c echoclient.Interface) echoClient { return echoClient{c} }\n", "", 1)
	for _, test := range []struct {
		name  string
		extra map[string]string
	}{
		{"declared twice", map[string]string{
			wrapperConstructorPath:                      wrapperConstructor,
			"client/wrappers/thrift/constructor_bsd.go": variant,
			wrapperCallsPath:                            wrapperCalls,
		}},
		{"unparseable sibling", map[string]string{
			wrapperConstructorPath:             wrapperConstructor,
			"client/wrappers/thrift/broken.go": "package thrift\n\nimport \"example.test/thrift/echo/echoclient\"\n\nfunc {\n",
			wrapperCallsPath:                   wrapperCalls,
		}},
		{"other package clause", map[string]string{
			"client/wrappers/thrift/constructor_test.go": strings.Replace(wrapperConstructor, "package thrift", "package thrift_test", 1),
			wrapperCallsPath: wrapperCalls,
		}},
	} {
		t.Run(test.name, func(t *testing.T) {
			view := buildYARPCCatalog(t, yarpcFixture{embedded: true, extra: test.extra})
			for _, field := range view.packageStructs {
				if field.Package == "thrift" {
					t.Fatalf("projected field in package thrift = %+v; want none", field)
				}
			}
			if view.packageStructScan != 1 {
				t.Fatalf("projection scan rows = %d", view.packageStructScan)
			}
			if calls, unresolved := scanSource(t, view.Resolver(), wrapperCallsPath, wrapperCalls); len(calls) != 0 || len(unresolved) != 0 {
				t.Fatalf("calls = %+v (unresolved %v); want none", calls, unresolved)
			}
		})
	}
	t.Run("scanned file declares the name", func(t *testing.T) {
		view := buildYARPCCatalog(t, yarpcFixture{embedded: true, extra: map[string]string{
			wrapperConstructorPath: wrapperConstructor,
		}})
		shadowing := strings.Replace(wrapperCalls, "import \"context\"\n",
			"import \"context\"\n\ntype echoClient struct{ c interface{ Echo(context.Context, string) (string, error) } }\n", 1)
		if calls, _ := scanSource(t, view.Resolver(), wrapperCallsPath, shadowing); slices.Contains(callOperations(calls), "/echo.Echo/echo") {
			t.Fatalf("a locally declared struct was overridden by the projection: %+v", calls)
		}
	})
}

// TestPackageStructBudgetWritesNoPartialProjection: a hit bound writes one
// unsupported status row and no field rows, so calls fall back to today's
// behavior rather than a partial view.
func TestPackageStructBudgetWritesNoPartialProjection(t *testing.T) {
	saved := packageStructBounds
	t.Cleanup(func() { packageStructBounds = saved })
	packageStructBounds.sources = 1
	view := buildYARPCCatalog(t, yarpcFixture{embedded: true, extra: map[string]string{
		wrapperConstructorPath: wrapperConstructor, wrapperCallsPath: wrapperCalls,
	}})
	if view.packageStructScan != 1 || len(view.packageStructs) != 0 {
		t.Fatalf("exhausted projection = %d scan rows, fields %+v", view.packageStructScan, view.packageStructs)
	}
	if calls, _ := scanSource(t, view.Resolver(), wrapperCallsPath, wrapperCalls); len(calls) != 0 {
		t.Fatalf("calls through an exhausted projection: %+v", calls)
	}
}
